F2 = [['CRD widgets 已建', 'alice(绑定 view)list widgets: no'], ['建带标签的 ClusterRole', ''], ['<0.1 秒', 'view 的 rules 里出现 widgets'], ['alice list widgets', 'yes;delete: no'], ['edit / admin', '也有 widgets']]
